"""Derive current browser coverage, retaining all preceding assertions except current aggregate counts."""
from setup_deseq2_reference import ROOT

EXTRA=r'''
 await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:8768/literature-review.html');await page.evaluate(()=>document.documentElement.dataset.theme='light');await page.locator('#tools-tab').click();await page.locator('#query').fill('hifiasm');const hc=page.locator('#results article').filter({has:page.getByRole('heading',{name:/^hifiasm \(/i})});assert.equal(await hc.count(),1);const ht=(await hc.innerText()).toLowerCase();for(const term of ['HifiasmWorkflowCli','0.14.2-r315','0.15.1-r328','0.16.1-r375','0.19.5-r587','0.19.5-r592','0.22.0-r689','upstream','streaming','FASTA','ONT','partial'])assert(ht.includes(term.toLowerCase()),term);await hc.screenshot({path:path.join(out,'hifiasm-card-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('hifiasm card shows six exact source editions, complete graph/FASTA admission and upstream assembly/phasing boundaries');
 const hr=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/tool-inventory.json'))).find(t=>t.id==='hifiasm');const hp=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/hifiasm-execution-development/VALIDATION.json')));assert.equal(hr.implementation_status,'upstream-adapter-validated');assert.equal(hr.development_candidate,hp.artifact.path);assert.equal(hr.development_candidate_sha256,hp.artifact.sha256);assert.equal(hr.development_cli_class,'org.jlinalg.cli.HifiasmWorkflowCli');assert.equal(hr.runtime_setup_cli_class,'org.jlinalg.cli.HifiasmSetupCli');assert.equal(hr.runtime_binding_cli_class,'org.jlinalg.cli.HifiasmRuntimeCli');for(const flag of ['analysis_installs_software','canonical_adapter_available','independent_consensus','independent_phasing','whole_package_implemented','whole_paper_reproduced'])assert.equal(hr[flag],false);checks.push('hifiasm catalog binds the exact validated development artifact with separate setup/runtime entry points and no release or biological credit');
 const hd=JSON.parse(fs.readFileSync(path.join(root,'tools/literature/hifiasm-use-reviews.json'))).reviews;assert.equal(hd.length,7);await page.locator('#papers-tab').click();for(const d of hd){const paper=papers.find(p=>p.paper_id===d.paper_id);await page.locator('#query').fill(paper.doi);assert.equal(await page.locator('#results article').count(),1);const content=clean(await page.locator('#'+d.paper_id).textContent());assert(content.includes(clean(d.review.use_summary)),d.paper_id+' summary');assert(content.includes(clean(d.review.implementation_scope_note)),d.paper_id+' source scope');}checks.push('all seven hifiasm paper roles retain literal versions, partial phasing, reuse, unreported settings and separate scaffolding/QC');
 await page.goto('http://127.0.0.1:8768/literature-warnings.html');const ha=page.locator('#hifiasm-required-actions');assert(await ha.isVisible());const hat=(await ha.innerText()).toLowerCase();for(const term of ['SKIP3','FAIL2','analysis_admitted=true','PROVISIONAL','NEW paths','installs nothing','allow_install','zlib','0.14.2-r315','0.15.1-r328','FASTQ','do not invent','r592','one bounded bucket','complete graph','sampled','Merqury','Cell Ranger'])assert(hat.includes(term.toLowerCase()),term);await ha.screenshot({path:path.join(out,'hifiasm-actions-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('prominent hifiasm warnings explain permitted setup, dependent-analysis skips, atomic failures, old Hi-C crashes, genuine qualities and capacity recovery');
 await page.setViewportSize({width:390,height:1000});await page.evaluate(()=>document.documentElement.dataset.theme='dark');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await ha.screenshot({path:path.join(out,'hifiasm-actions-mobile-dark.png'),style:'header{visibility:hidden!important}'});assert.equal(errors.length,0,errors.join('\n'));const hroles=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/hifiasm-role-coverage.json')));assert.equal(hroles.prior_reviews,993);assert.equal(hroles.unchanged_prior_reviews,993);assert.equal(hroles.new_reviews,7);assert.equal(hroles.total_reviews,1000);assert.equal(hroles.supporting_pointers,347);checks.push('hifiasm dark warnings fit390px without overflow or browser errors and exact seven-role extension preserves all993 previous reviews');
'''


def generated():
    tools=ROOT/'tools/literature';text=(tools/'check_gseapy_review_ui.cjs').read_text(encoding='utf8')
    for old,new in [("['upstream-adapter-validated',71],['missing',253]","['upstream-adapter-validated',72],['missing',252]"),('400 cataloged tools,88 new integrations,253 missing','400 cataloged tools,89 new integrations,252 missing'),('assert.equal(gu.length,993)','assert.equal(gu.length,1000)'),('length,0),344)','length,0),347)'),('993 roles and344 support pointers','1000 roles and347 support pointers'),('gseapy-ui-verification.json','hifiasm-ui-verification.json'),('Passed26 focused current CellPhoneDB, Palantir, scFates and GSEApy browser checks','Passed31 focused current CellPhoneDB, Palantir, scFates, GSEApy and hifiasm browser checks')]:assert text.count(old)==1,old;text=text.replace(old,new)
    marker=' const inventory=JSON.parse';assert text.count(marker)==1;text=text.replace(marker,EXTRA+marker);wrapper=(tools/'validate_gseapy_catalog_ui.py').read_text(encoding='utf8').replace('gseapy','hifiasm').replace('check_hifiasm_review_ui.cjs','check_hifiasm_catalog_review_ui.cjs');return {tools/'check_hifiasm_catalog_review_ui.cjs':text.encode(),tools/'validate_hifiasm_catalog_ui.py':wrapper.encode()}


def verify():
    for path,raw in generated().items():assert path.read_bytes()==raw,'Focused UI derivation differs: '+str(path)


if __name__=='__main__':
    for path,raw in generated().items():
        if path.exists():assert path.read_bytes()==raw
        else:path.write_bytes(raw)
    verify();print('Prepared299 unchanged general and31 current focused browser checks')
